// Normaliza el input: HTTP directo o llamada desde WF-C (Slack Events)
const raw = $input.first().json || {};
const body = raw.body?.message || raw.body?.text || raw.body?.query || raw.body?.pregunta
  ? raw.body
  : (raw.body?.body || raw.body || raw);

const message = body.message || body.text || body.query || body.pregunta || body.input || '';
const session_id = body.session_id || body.user_id || raw.headers?.['x-session-id'] || 'default';

// Campos Slack (solo presentes si viene de WF-C)
const slack_channel_id = body.slack_channel_id || null;
const slack_thread_ts  = body.slack_thread_ts  || null;
const slack_user       = body.slack_user       || null;

if (!message || !String(message).trim()) {
  throw new Error('Falta el campo message en el body. Recibido: ' + JSON.stringify(raw).slice(0, 500));
}
return [{ json: { message: String(message).trim(), session_id, slack_channel_id, slack_thread_ts, slack_user } }];

const agentOutput = $('Agente OPEX (Claude)').first().json.output || 'Sin respuesta del agente.';
const channelId  = $('Normalizar input').first().json.slack_channel_id;
const threadTs   = $('Normalizar input').first().json.slack_thread_ts;
const slackUser  = $('Normalizar input').first().json.slack_user || '';

// Slack mrkdwn: límite 3000 chars por bloque de texto
const text = agentOutput.length > 2900 ? agentOutput.slice(0, 2897) + '...' : agentOutput;

const payload = {
  channel: channelId,
  text: `🔮 *Oráculo del OPEX*\n\n${text}`,
  blocks: [
    {
      type: 'section',
      text: { type: 'mrkdwn', text: `🔮 *Oráculo del OPEX*\n\n${text}` }
    },
    {
      type: 'context',
      elements: [{ type: 'mrkdwn', text: `Powered by Claude Sonnet${slackUser ? ' · <@' + slackUser + '>' : ''}` }]
    }
  ]
};

// Si vino de un hilo, responder en el mismo hilo
if (threadTs) payload.thread_ts = threadTs;

return [{ json: { payload } }];
